function roi(initial, final){ if(initial===0) return null; return (final-initial)/initial*100; }
function cagr(initial, final, years){ if(initial<=0||years<=0) return null; return Math.pow(final/initial, 1/years)-1; }
function multiple(initial, final){ if(initial===0) return null; return final/initial; }
function totalReturnSeries(arr){ // arr 为逐年净值，返回各年 ROI%
  var out=[]; for(var i=0;i<arr.length;i++){ out.push(roi(arr[0], arr[i])); } return out;
}
var EXPORTS={roi:roi, cagr:cagr, multiple:multiple, totalReturnSeries:totalReturnSeries};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RoiForgePure = EXPORTS; }
